print({k:(min(v),max(v)) for k,v in segs.items()})
# standard point in polygon, boundary treated outside
def pip(x,y,poly):
    inside=False
    n=len(poly)
    for i in range(n):
        x1,y1=poly[i]; x2,y2=poly[(i+1)%n]
        # boundary detection
        cross=(x-x1)*(y2-y1)-(y-y1)*(x2-x1)
        if abs(cross)<1e-9 and min(x1,x2)-1e-9<=x<=max(x1,x2)+1e-9 and min(y1,y2)-1e-9<=y<=max(y1,y2)+1e-9:
            return False
        if (y1>y)!=(y2>y):
            xin=x1+(y-y1)*(x2-x1)/(y2-y1)
            if x<xin: inside=not inside
    return inside
actual={(r,c) for r in range(16) for c in range(16) if demo2_out[r][c]==2}
for a,b in zip(sorted(segs), sorted(segs)[1:]):
    alo,ahi=min(segs[a]),max(segs[a]);blo,bhi=min(segs[b]),max(segs[b])
    poly=[(a,alo),(a,ahi),(b,bhi),(b,blo)] # vertical left, bottom cross, vertical right, top cross
    fill={(r,c) for r in range(16) for c in range(16) if pip(c-r,r,poly)}
    print((a,b),len(fill),len(fill&actual),len(actual&fill),sorted((r,c-r) for r,c in fill)[:10])
    print(' differences', 'miss', sorted(actual&{(r,c) for r in range(16) for c in range(16) if a<c-r<b}-fill)[:30])

