def convex_hull(pts):
    pts=sorted(set(pts))
    if len(pts)<=1: return pts
    def cr(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for p in pts:
        while len(lo)>=2 and cr(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    hi=[]
    for p in reversed(pts):
        while len(hi)>=2 and cr(hi[-2],hi[-1],p)<=0: hi.pop()
        hi.append(p)
    return lo[:-1]+hi[:-1]
pts2=[(c-r,r) for r,row in enumerate(demo2_in) for c,v in enumerate(row) if v==7]
h2=convex_hull(pts2)
print('hull',h2)
hull_in={(r,c) for r in range(16) for c in range(16) if pip(c-r,r,h2)}
print(len(hull_in),len(actual),len(hull_in&actual), 'pred-only',len(hull_in-actual), 'miss',len(actual-hull_in))
print('miss',sorted((r,c-r) for r,c in actual-hull_in))
print('extra sample',sorted((r,c-r) for r,c in hull_in-actual)[:100])

