# Verify the antidiagonal-coordinate rule against both demo outputs, per adjacent tracks.
def pfill_for_grid(inp, out_color):
    tracks=defaultdict(list)
    for r,row in enumerate(inp):
      for c,v in enumerate(row):
        if v != 8: tracks[c-r].append((r,c))
    ks=sorted(tracks)
    pred=set()
    for a,b in zip(ks,ks[1:]):
      va,vb=tracks[a],tracks[b]
      pa=[r+c for r,c in va]; pb=[r+c for r,c in vb]
      lo=max(min(pa),min(pb)); hi=min(max(pa),max(pb))
      if lo>hi: continue
      for r in range(16):
       for c in range(16):
        if inp[r][c]==8 and a<c-r<b and lo<=r+c<=hi:
         pred.add((r,c))
    actual2={(r,c) for r,row in enumerate(out_color) for c,v in enumerate(row) if v==2}
    return pred,actual2
