def active_p_rule(inp):
    tracks=defaultdict(list)
    for r,row in enumerate(inp):
      for c,v in enumerate(row):
       if v!=8:
        tracks[c-r].append(r+c)
    intervals={x:(min(ps),max(ps)) for x,ps in tracks.items()}
    out=[row[:] for row in inp]
    for r in range(len(inp)):
      for c in range(len(inp[0])):
       if inp[r][c]!=8: continue
       x=c-r; p=r+c
       active=sorted(x0 for x0,(lo,hi) in intervals.items() if lo<=p<=hi)
       if any(active[i]<x<active[i+1] for i in range(len(active)-1)):
        out[r][c]=2
    return out
