def segment_tracks(inp):
    pts=defaultdict(list)
    for r,row in enumerate(inp):
      for c,v in enumerate(row):
       if v!=8: pts[c-r].append(r)
    # segment contiguous in row r for fixed offset
    segs={}
    for x,rs in pts.items():
      rs=sorted(rs); groups=[]
      for r in rs:
       if not groups or r>groups[-1][-1]+1: groups.append([r])
       else: groups[-1].append(r)
      segs[x]=[(x+2*g[0],x+2*g[-1]) for g in groups]
    return segs

